create extension if not exists pgcrypto;
create table if not exists public.sets (id uuid primary key default gen_random_uuid(),name text not null,code text,release_date date,created_at timestamptz not null default now());
create table if not exists public.cards (id uuid primary key default gen_random_uuid(),name text not null,set_id uuid references public.sets(id) on delete set null,card_number text,rarity text,language text not null default 'English',condition text not null default 'Near Mint',image_url text,price numeric(12,2) not null default 0 check(price>=0),stock integer not null default 0 check(stock>=0),published boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.orders (id uuid primary key default gen_random_uuid(),customer_name text,customer_email text,customer_phone text,status text not null default 'pending',total numeric(12,2) not null default 0 check(total>=0),notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.order_items (id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,card_id uuid not null references public.cards(id) on delete restrict,quantity integer not null check(quantity>0),unit_price numeric(12,2) not null check(unit_price>=0),created_at timestamptz not null default now());
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade,role text not null default 'tester' check(role in ('admin','tester')),created_at timestamptz not null default now());
alter table public.sets enable row level security;alter table public.cards enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;alter table public.profiles enable row level security;
grant select on public.sets to anon,authenticated;grant select on public.cards to anon,authenticated;grant insert,update,delete on public.cards to authenticated;grant insert on public.orders to anon,authenticated;grant insert on public.order_items to anon,authenticated;grant select,update on public.orders to authenticated;grant select on public.order_items to authenticated;grant select on public.profiles to authenticated;
drop policy if exists "public read sets" on public.sets;create policy "public read sets" on public.sets for select to anon,authenticated using(true);
drop policy if exists "public read published cards" on public.cards;create policy "public read published cards" on public.cards for select to anon,authenticated using(published=true);
drop policy if exists "authenticated manage cards" on public.cards;create policy "admin manage cards" on public.cards for all to authenticated using((select coalesce((auth.jwt()->'app_metadata'->>'role'),'')='admin')) with check((select coalesce((auth.jwt()->'app_metadata'->>'role'),'')='admin'));
drop policy if exists "public create orders" on public.orders;create policy "public create orders" on public.orders for insert to anon,authenticated with check(true);
drop policy if exists "authenticated read orders" on public.orders;create policy "admin read orders" on public.orders for select to authenticated using((select coalesce((auth.jwt()->'app_metadata'->>'role'),'')='admin'));
drop policy if exists "authenticated update orders" on public.orders;create policy "admin update orders" on public.orders for update to authenticated using((select coalesce((auth.jwt()->'app_metadata'->>'role'),'')='admin')) with check((select coalesce((auth.jwt()->'app_metadata'->>'role'),'')='admin'));
drop policy if exists "public create order items" on public.order_items;create policy "public create order items" on public.order_items for insert to anon,authenticated with check(true);
drop policy if exists "authenticated read order items" on public.order_items;create policy "admin read order items" on public.order_items for select to authenticated using((select coalesce((auth.jwt()->'app_metadata'->>'role'),'')='admin'));
drop policy if exists "read own profile" on public.profiles;create policy "read own profile" on public.profiles for select to authenticated using((select auth.uid())=id);
create index if not exists cards_published_idx on public.cards(published);create index if not exists cards_set_idx on public.cards(set_id);create index if not exists cards_name_idx on public.cards(name);create index if not exists order_items_order_idx on public.order_items(order_id);create index if not exists order_items_card_idx on public.order_items(card_id);
insert into storage.buckets(id,name,public) values('card-images','card-images',true) on conflict(id) do update set public=true;
drop policy if exists "public read card images" on storage.objects;create policy "public read card images" on storage.objects for select to public using(bucket_id='card-images');
drop policy if exists "authenticated upload card images" on storage.objects;create policy "admin upload card images" on storage.objects for insert to authenticated with check(bucket_id='card-images' and coalesce((auth.jwt()->'app_metadata'->>'role'),'')='admin');
drop policy if exists "authenticated update card images" on storage.objects;create policy "admin update card images" on storage.objects for update to authenticated using(bucket_id='card-images' and coalesce((auth.jwt()->'app_metadata'->>'role'),'')='admin') with check(bucket_id='card-images' and coalesce((auth.jwt()->'app_metadata'->>'role'),'')='admin');
drop policy if exists "authenticated delete card images" on storage.objects;create policy "admin delete card images" on storage.objects for delete to authenticated using(bucket_id='card-images' and coalesce((auth.jwt()->'app_metadata'->>'role'),'')='admin');
